<h1><?= e($doc['title']) ?></h1><?php if(!empty($canAdmin)): ?><p><a class="btn-sm" href="/documents/<?= (int)$doc['id'] ?>/access">Accesso diretto al documento</a></p><?php endif; ?><p class="muted">Slug: <code>/<?= e($doc['slug']) ?></code> · Aggiornato: <?= e((string)$doc['updated_at']) ?> · <a href="/documents/<?= (int)$doc['id'] ?>/revisions">Revisioni</a><?php if($canWrite): ?> · <a href="/documents/<?= (int)$doc['id'] ?>/edit">Modifica</a><?php endif; ?><?php if(!empty($canAdmin)): ?> · <a href="/documents/<?= (int)$doc['id'] ?>/acl">Permessi</a> · <a href="/documents/<?= (int)$doc['id'] ?>/shares">Link pubblici</a><?php endif; ?></p><form method="post" action="/documents/<?= (int)$doc['id'] ?>/favorite" class="inline-form"><?= \Archium\Support\Csrf::field() ?><button class="btn-sm favorite-button"><?= !empty($isFavorite)?'★ Rimuovi dai preferiti':'☆ Aggiungi ai preferiti' ?></button></form><?php if(!empty($tags)): ?><p class="tag-row"><?php foreach($tags as $tag): ?><span class="tag-chip"><?= e($tag['name']) ?></span><?php endforeach; ?></p><?php endif; ?><div class="card doc-content"><?= $html ?></div><?php if(!empty($children)): ?><h2>Sotto-documenti</h2><ul><?php foreach($children as $child): ?><li><a href="/documents/<?= (int)$child['id'] ?>"><?= e($child['title']) ?></a></li><?php endforeach; ?></ul><?php endif; ?><?php if($canDelete): ?><form method="post" action="/documents/<?= (int)$doc['id'] ?>/delete" class="inline-form"><?= \Archium\Support\Csrf::field() ?><button class="btn-sm danger">Sposta nel cestino</button></form><?php endif; ?>